//! Shared SQLite connection configuration.

#![expect(
    clippy::disallowed_methods,
    reason = "this is the centralized SQLite connection shim"
)]

use crate::DbTelemetry;
use crate::migrations::repair_legacy_recency_migration_version;
use crate::runtime::RuntimeDbInitError;
use crate::telemetry;
use crate::telemetry::DbKind;
use codex_utils_absolute_path::AbsolutePathBuf;
use log::LevelFilter;
use sqlx::ConnectOptions;
use sqlx::Connection;
use sqlx::Error;
use sqlx::SqlitePool;
use sqlx::migrate::Migrator;
use sqlx::sqlite::SqliteAutoVacuum;
use sqlx::sqlite::SqliteConnectOptions;
use sqlx::sqlite::SqliteJournalMode;
use sqlx::sqlite::SqlitePoolOptions;
use sqlx::sqlite::SqliteSynchronous;
use std::path::Path;
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;
use std::time::Instant;

const LOGS_DB_FILENAME: &str = "logs_2.sqlite";
const GOALS_DB_FILENAME: &str = "goals_1.sqlite";
const MEMORIES_DB_FILENAME: &str = "memories_1.sqlite";
const QUEUE_DB_FILENAME: &str = "queue_1.sqlite";
const STATE_DB_FILENAME: &str = "state_5.sqlite";
const THREAD_HISTORY_DB_FILENAME: &str = "thread_history_1.sqlite";

#[derive(Clone, Copy)]
struct RuntimeDbSpec {
    label: &'static str,
    filename: &'static str,
    kind: DbKind,
    open_phase: &'static str,
    migrate_phase: &'static str,
}

impl RuntimeDbSpec {
    fn path(self, codex_home: &Path) -> PathBuf {
        codex_home.join(self.filename)
    }
}

const STATE_DB: RuntimeDbSpec = RuntimeDbSpec {
    label: "state DB",
    filename: STATE_DB_FILENAME,
    kind: DbKind::State,
    open_phase: "open_state",
    migrate_phase: "migrate_state",
};

const LOGS_DB: RuntimeDbSpec = RuntimeDbSpec {
    label: "log DB",
    filename: LOGS_DB_FILENAME,
    kind: DbKind::Logs,
    open_phase: "open_logs",
    migrate_phase: "migrate_logs",
};

const GOALS_DB: RuntimeDbSpec = RuntimeDbSpec {
    label: "goals DB",
    filename: GOALS_DB_FILENAME,
    kind: DbKind::Goals,
    open_phase: "open_goals",
    migrate_phase: "migrate_goals",
};

const MEMORIES_DB: RuntimeDbSpec = RuntimeDbSpec {
    label: "memories DB",
    filename: MEMORIES_DB_FILENAME,
    kind: DbKind::Memories,
    open_phase: "open_memories",
    migrate_phase: "migrate_memories",
};

const QUEUE_DB: RuntimeDbSpec = RuntimeDbSpec {
    label: "queue DB",
    filename: QUEUE_DB_FILENAME,
    kind: DbKind::Queue,
    open_phase: "open_queue",
    migrate_phase: "migrate_queue",
};

const THREAD_HISTORY_DB: RuntimeDbSpec = RuntimeDbSpec {
    label: "thread history DB",
    filename: THREAD_HISTORY_DB_FILENAME,
    kind: DbKind::ThreadHistory,
    open_phase: "open_thread_history",
    migrate_phase: "migrate_thread_history",
};

const RUNTIME_DBS: [RuntimeDbSpec; 6] = [
    STATE_DB,
    LOGS_DB,
    GOALS_DB,
    MEMORIES_DB,
    QUEUE_DB,
    THREAD_HISTORY_DB,
];

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RuntimeDbPath {
    pub label: &'static str,
    pub path: PathBuf,
}

/// Resolved configuration shared by all Codex SQLite connections.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SqliteConfig {
    sqlite_home: AbsolutePathBuf,
}

impl SqliteConfig {
    pub fn from_sqlite_home(sqlite_home: AbsolutePathBuf) -> Self {
        Self { sqlite_home }
    }

    pub fn new_for_testing(sqlite_home: AbsolutePathBuf) -> Self {
        Self::from_sqlite_home(sqlite_home)
    }

    /// Open an isolated, single-connection in-memory database for schema tests.
    ///
    /// Repeated pool acquisitions retain the same in-memory database.
    pub async fn open_in_memory_pool_for_testing() -> Result<SqlitePool, Error> {
        SqlitePoolOptions::new()
            .max_connections(1)
            .connect("sqlite::memory:")
            .await
    }

    pub fn home(&self) -> &Path {
        self.sqlite_home.as_path()
    }

    /// Return the path to the primary state database.
    pub fn state_db_path(&self) -> PathBuf {
        STATE_DB.path(self.home())
    }

    /// Return the path to the logs database.
    pub fn logs_db_path(&self) -> PathBuf {
        LOGS_DB.path(self.home())
    }

    /// Return the path to the goals database.
    pub fn goals_db_path(&self) -> PathBuf {
        GOALS_DB.path(self.home())
    }

    /// Return the path to the memories database.
    pub fn memories_db_path(&self) -> PathBuf {
        MEMORIES_DB.path(self.home())
    }

    /// Return the path to the durable user-message queue database.
    pub fn queue_db_path(&self) -> PathBuf {
        QUEUE_DB.path(self.home())
    }

    /// Return the path to the paginated thread-history database.
    pub fn thread_history_db_path(&self) -> PathBuf {
        THREAD_HISTORY_DB.path(self.home())
    }

    /// Return the paths to every database managed by the state runtime.
    pub fn runtime_db_paths(&self) -> Vec<RuntimeDbPath> {
        RUNTIME_DBS
            .iter()
            .map(|spec| RuntimeDbPath {
                label: spec.label,
                path: spec.path(self.home()),
            })
            .collect()
    }

    pub(super) async fn open_state_db(
        &self,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        // New state DBs should use incremental auto-vacuum, but retrofitting an
        // existing DB requires a full VACUUM. Do not attempt that during process
        // startup: it is maintenance work that can contend with foreground writers.
        self.open_runtime_db(STATE_DB, migrator, telemetry_override)
            .await
    }

    pub(super) async fn open_logs_db(
        &self,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        self.open_runtime_db(LOGS_DB, migrator, telemetry_override)
            .await
    }

    pub(super) async fn open_goals_db(
        &self,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        self.open_runtime_db(GOALS_DB, migrator, telemetry_override)
            .await
    }

    pub(super) async fn open_memories_db(
        &self,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        self.open_runtime_db(MEMORIES_DB, migrator, telemetry_override)
            .await
    }

    pub(super) async fn open_queue_db(
        &self,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        self.open_runtime_db(QUEUE_DB, migrator, telemetry_override)
            .await
    }

    pub(super) async fn open_thread_history_db(
        &self,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        self.open_runtime_db(THREAD_HISTORY_DB, migrator, telemetry_override)
            .await
    }

    async fn open_runtime_db(
        &self,
        spec: RuntimeDbSpec,
        migrator: &Migrator,
        telemetry_override: Option<&dyn DbTelemetry>,
    ) -> anyhow::Result<SqlitePool> {
        let path = spec.path(self.home());
        let started = Instant::now();
        let pool_result = self
            .open_read_write_pool(&path)
            .await
            .map_err(anyhow::Error::from);
        telemetry::record_init_result(
            telemetry_override,
            spec.kind,
            spec.open_phase,
            started.elapsed(),
            &pool_result,
        );
        let pool = pool_result.map_err(|source| {
            RuntimeDbInitError::new(spec.label, "open", path.as_path(), source)
        })?;
        let started = Instant::now();
        let migrate_result = async {
            if matches!(spec.kind, DbKind::State) {
                repair_legacy_recency_migration_version(&pool, migrator).await?;
            }
            migrator.run(&pool).await.map_err(anyhow::Error::from)
        }
        .await;
        telemetry::record_init_result(
            telemetry_override,
            spec.kind,
            spec.migrate_phase,
            started.elapsed(),
            &migrate_result,
        );
        if let Err(source) = migrate_result {
            pool.close().await;
            return Err(
                RuntimeDbInitError::new(spec.label, "migrate", path.as_path(), source).into(),
            );
        }
        Ok(pool)
    }

    /// Open a writable Codex SQLite database, creating it if necessary.
    pub async fn open_read_write_pool(&self, path: &Path) -> Result<SqlitePool, Error> {
        let options = SqliteConnectOptions::new()
            .filename(path)
            .create_if_missing(true)
            .journal_mode(SqliteJournalMode::Wal)
            .synchronous(SqliteSynchronous::Normal)
            .auto_vacuum(SqliteAutoVacuum::Incremental)
            .busy_timeout(Duration::from_secs(5))
            .log_statements(LevelFilter::Off);
        SqlitePoolOptions::new()
            .max_connections(5)
            .connect_with(options)
            .await
    }

    /// Open an append-only evidence database with full synchronous durability.
    ///
    /// Evidence owners remain responsible for their own migrations and must
    /// not route authoritative corruption through the rebuildable state-DB
    /// recovery path.
    pub async fn open_durable_evidence_pool(&self, path: &Path) -> Result<SqlitePool, Error> {
        let options = SqliteConnectOptions::new()
            .filename(path)
            .create_if_missing(true)
            .journal_mode(SqliteJournalMode::Wal)
            .synchronous(SqliteSynchronous::Full)
            .foreign_keys(true)
            .busy_timeout(Duration::from_secs(5))
            .log_statements(LevelFilter::Off);
        SqlitePoolOptions::new()
            .max_connections(5)
            .connect_with(options)
            .await
    }

    /// Open an evidence writer whose explicit and implicit commits use `commit_allowed`.
    ///
    /// The owner must keep the returned pool private and retain the independently
    /// authenticated Current/writer state checked by the callback. This connection
    /// API does not establish that authority or bind a protected checkpoint.
    ///
    /// Every new connection installs the commit hook before it can be checked out.
    /// Both new and reused connections await `before_checkout`; its completion is
    /// coordination, not permission to commit. A failed witness refresh must leave
    /// `commit_allowed` false. The commit hook remains the final write boundary.
    ///
    /// `commit_allowed` runs synchronously inside SQLite and must be bounded,
    /// nonblocking, and must not call SQLite. `before_checkout` must not acquire
    /// from this pool or retain a lock needed by the commit callback. The SQLite
    /// handle lock is released before awaiting checkout coordination.
    ///
    /// Connection setup precedes hook installation, so callers must hold their
    /// file/initialization fence while opening the pool. This is not a replacement
    /// for the descriptor-bound recovery API or the owner's whole-store gate.
    pub async fn open_coordinated_durable_evidence_pool<F, C, Fut>(
        &self,
        path: &Path,
        commit_allowed: F,
        before_checkout: C,
    ) -> Result<SqlitePool, Error>
    where
        F: Fn() -> bool + Send + Sync + 'static,
        C: Fn() -> Fut + Send + Sync + 'static,
        Fut: std::future::Future<Output = ()> + Send + 'static,
    {
        let commit_allowed = Arc::new(commit_allowed);
        let before_checkout = Arc::new(before_checkout);
        let before_reuse = Arc::clone(&before_checkout);
        let options = SqliteConnectOptions::new()
            .filename(path)
            .create_if_missing(true)
            .journal_mode(SqliteJournalMode::Wal)
            .synchronous(SqliteSynchronous::Full)
            .foreign_keys(true)
            .busy_timeout(Duration::from_secs(5))
            .log_statements(LevelFilter::Off);
        SqlitePoolOptions::new()
            .max_connections(5)
            .after_connect(move |connection, _metadata| {
                let commit_allowed = Arc::clone(&commit_allowed);
                let before_checkout = Arc::clone(&before_checkout);
                Box::pin(async move {
                    {
                        let mut handle = connection.lock_handle().await?;
                        handle.set_commit_hook(move || commit_allowed());
                    }
                    before_checkout().await;
                    Ok(())
                })
            })
            .before_acquire(move |_connection, _metadata| {
                let before_checkout = Arc::clone(&before_reuse);
                Box::pin(async move {
                    before_checkout().await;
                    Ok(true)
                })
            })
            .connect_with(options)
            .await
    }

    /// Checkpoint a private recovery candidate after all validation handles close.
    ///
    /// The owner must hold its recovery fence and pass a newly materialized copy,
    /// never the suspect source. A single connection permits the journal-mode
    /// switch that a pool's other live handles would otherwise block.
    pub async fn checkpoint_private_recovery_database(&self, path: &Path) -> Result<(), Error> {
        let options = SqliteConnectOptions::new()
            .filename(path)
            .create_if_missing(false)
            .synchronous(SqliteSynchronous::Full)
            .foreign_keys(true)
            .busy_timeout(Duration::from_secs(5))
            .log_statements(LevelFilter::Off);
        let mut connection = options.connect().await?;
        let checkpoint = async {
            let (busy, _, _): (i32, i32, i32) = sqlx::query_as("PRAGMA wal_checkpoint(TRUNCATE)")
                .fetch_one(&mut connection)
                .await?;
            if busy != 0 {
                return Err(Error::Protocol(
                    "recovery candidate checkpoint is busy".to_string(),
                ));
            }
            let journal_mode: String = sqlx::query_scalar("PRAGMA journal_mode=DELETE")
                .fetch_one(&mut connection)
                .await?;
            if !journal_mode.eq_ignore_ascii_case("delete") {
                return Err(Error::Protocol(
                    "recovery candidate could not checkpoint to a single-file cut".to_string(),
                ));
            }
            Ok(())
        }
        .await;
        let close = connection.close().await;
        checkpoint?;
        close
    }

    /// Retained only so callers fail closed instead of reopening a suspect
    /// lexical source path with a reconnect-capable writer pool.
    ///
    /// Writable recovery binds [`Self::bind_existing_recovery_database`],
    /// captures an identity-checked copy from retained descriptors, validates
    /// that copy against an independently retained current-cut witness, and
    /// opens only the new generation. This path-based source reopen therefore
    /// remains deliberately unavailable.
    pub async fn open_existing_durable_evidence_pool(
        &self,
        path: &Path,
    ) -> Result<SqlitePool, Error> {
        let _ = (self, path);
        Err(Error::Protocol(
            "path-based SQLite recovery is disabled".to_string(),
        ))
    }

    /// Open an existing Codex SQLite database without creating or modifying it.
    pub async fn open_read_only_pool(&self, path: &Path) -> Result<SqlitePool, Error> {
        let options = SqliteConnectOptions::new()
            .filename(path)
            .create_if_missing(false)
            .read_only(true)
            .log_statements(LevelFilter::Off);
        SqlitePoolOptions::new()
            .max_connections(1)
            .connect_with(options)
            .await
    }
}

#[cfg(test)]
#[path = "sqlite_commit_gate_tests.rs"]
mod commit_gate_tests;

use super::SqliteConfig;
use crate::runtime::test_support::create_private_test_directory;
use crate::runtime::test_support::unique_temp_dir;
use anyhow::Context;
use codex_utils_absolute_path::test_support::PathExt;
use pretty_assertions::assert_eq;
use sqlx::SqlitePool;
use std::future::Future;
use std::path::PathBuf;
use std::pin::Pin;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;
use std::sync::atomic::Ordering;
use std::task::Poll;
use std::time::Duration;
use tokio::sync::Semaphore;
use tokio::time::timeout;

const CHECKOUT_DEADLINE: Duration = Duration::from_secs(5);

struct Fixture {
    home: PathBuf,
    database: PathBuf,
    sqlite: SqliteConfig,
}

impl Fixture {
    async fn new() -> anyhow::Result<Self> {
        let home = unique_temp_dir();
        create_private_test_directory(&home)?;
        let fixture = Self {
            database: home.join("commit-gate.sqlite"),
            sqlite: SqliteConfig::new_for_testing(home.as_path().abs()),
            home,
        };
        let pool = fixture
            .sqlite
            .open_durable_evidence_pool(&fixture.database)
            .await?;
        let result = sqlx::query("CREATE TABLE evidence (value INTEGER NOT NULL)")
            .execute(&pool)
            .await;
        pool.close().await;
        result?;
        Ok(fixture)
    }

    async fn open(
        &self,
        allowed: Arc<AtomicBool>,
        gate: Arc<CheckoutGate>,
    ) -> Result<SqlitePool, sqlx::Error> {
        self.sqlite
            .open_coordinated_durable_evidence_pool(
                &self.database,
                move || allowed.load(Ordering::SeqCst),
                move || {
                    let gate = Arc::clone(&gate);
                    async move { gate.wait().await }
                },
            )
            .await
    }

    async fn persisted_rows(&self) -> anyhow::Result<Vec<i64>> {
        let reader = self.sqlite.open_read_only_pool(&self.database).await?;
        let result = sqlx::query_scalar("SELECT value FROM evidence ORDER BY value")
            .fetch_all(&reader)
            .await;
        reader.close().await;
        Ok(result?)
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.home);
    }
}

struct CheckoutGate {
    blocked: AtomicBool,
    entered: Semaphore,
    resume: Semaphore,
}

impl CheckoutGate {
    fn ready() -> Self {
        Self {
            blocked: AtomicBool::new(false),
            entered: Semaphore::new(0),
            resume: Semaphore::new(0),
        }
    }

    fn blocked() -> Self {
        let gate = Self::ready();
        gate.blocked.store(true, Ordering::SeqCst);
        gate
    }

    async fn wait(&self) {
        if self.blocked.load(Ordering::SeqCst) {
            self.entered.add_permits(1);
            self.resume
                .acquire()
                .await
                .expect("checkout release semaphore remains open")
                .forget();
        }
    }

    fn release(&self) {
        self.blocked.store(false, Ordering::SeqCst);
        self.resume.add_permits(1);
    }
}

async fn assert_waits_for_checkout<F>(
    operation: &mut Pin<Box<F>>,
    gate: &CheckoutGate,
) -> anyhow::Result<()>
where
    F: Future,
    F::Output: std::fmt::Debug,
{
    timeout(CHECKOUT_DEADLINE, async {
        tokio::select! {
            result = operation.as_mut() => {
                anyhow::bail!("checkout completed before its callback entered: {result:?}");
            }
            permit = gate.entered.acquire() => permit?.forget(),
        }
        let polled = std::future::poll_fn(|cx| Poll::Ready(operation.as_mut().poll(cx))).await;
        assert!(
            polled.is_pending(),
            "checkout completed before release: {polled:?}"
        );
        Ok(())
    })
    .await?
}

fn assert_commit_veto(error: sqlx::Error) {
    let sqlx::Error::Database(error) = error else {
        panic!("expected SQLite commit-hook veto, got {error:?}");
    };
    let expected = libsqlite3_sys::SQLITE_CONSTRAINT_COMMITHOOK.to_string();
    assert_eq!(
        error.code().as_deref(),
        Some(expected.as_str()),
        "expected SQLITE_CONSTRAINT_COMMITHOOK"
    );
}

#[tokio::test]
async fn commit_gate_rejects_explicit_transaction_after_revocation() -> anyhow::Result<()> {
    let fixture = Fixture::new().await?;
    let allowed = Arc::new(AtomicBool::new(true));
    let pool = fixture
        .open(Arc::clone(&allowed), Arc::new(CheckoutGate::ready()))
        .await?;
    let sqlite_version: String = sqlx::query_scalar("SELECT sqlite_version()")
        .fetch_one(&pool)
        .await?;
    eprintln!("commit_gate_runtime: sqlite_version={sqlite_version}");
    let mut transaction = pool.begin().await?;
    sqlx::query("INSERT INTO evidence VALUES (1)")
        .execute(&mut *transaction)
        .await?;
    allowed.store(false, Ordering::SeqCst);
    assert_commit_veto(
        transaction
            .commit()
            .await
            .expect_err("revocation must veto the actual commit"),
    );
    assert_eq!(fixture.persisted_rows().await?, Vec::<i64>::new());

    allowed.store(true, Ordering::SeqCst);
    sqlx::query("INSERT INTO evidence VALUES (2)")
        .execute(&pool)
        .await?;
    pool.close().await;
    assert_eq!(fixture.persisted_rows().await?, vec![2]);
    Ok(())
}

#[tokio::test]
async fn commit_gate_covers_pool_growth_and_replacement() -> anyhow::Result<()> {
    let fixture = Fixture::new().await?;
    let allowed = Arc::new(AtomicBool::new(false));
    let pool = fixture
        .open(Arc::clone(&allowed), Arc::new(CheckoutGate::ready()))
        .await?;
    let mut connections = Vec::new();
    for _ in 0..5 {
        let mut connection = pool.acquire().await?;
        assert_commit_veto(
            sqlx::query("INSERT INTO evidence VALUES (3)")
                .execute(&mut *connection)
                .await
                .expect_err("every connection must veto an implicit commit"),
        );
        connections.push(connection);
    }
    assert_eq!(pool.size(), 5);
    connections.pop().context("fifth connection exists")?.close().await?;
    let mut replacement = pool.acquire().await?;
    assert_commit_veto(
        sqlx::query("INSERT INTO evidence VALUES (4)")
            .execute(&mut *replacement)
            .await
            .expect_err("replacement connection must retain the commit gate"),
    );
    assert_eq!(fixture.persisted_rows().await?, Vec::<i64>::new());

    allowed.store(true, Ordering::SeqCst);
    sqlx::query("INSERT INTO evidence VALUES (5)")
        .execute(&mut *replacement)
        .await?;
    replacement.close().await?;
    for connection in connections {
        connection.close().await?;
    }
    pool.close().await;
    assert_eq!(fixture.persisted_rows().await?, vec![5]);
    Ok(())
}

#[tokio::test]
async fn checkout_callback_blocks_initial_connect_and_reused_connection() -> anyhow::Result<()> {
    let fixture = Fixture::new().await?;
    let gate = Arc::new(CheckoutGate::blocked());
    let mut opening = Box::pin(fixture.open(Arc::new(AtomicBool::new(true)), Arc::clone(&gate)));
    assert_waits_for_checkout(&mut opening, &gate).await?;
    gate.release();
    let pool = timeout(CHECKOUT_DEADLINE, opening).await??;

    let mut held = Vec::new();
    for _ in 0..5 {
        held.push(pool.acquire().await?);
    }
    let mut returned = held.pop().context("fifth connection exists")?;
    sqlx::query("CREATE TEMP TABLE checkout_marker (value INTEGER)")
        .execute(&mut *returned)
        .await?;
    sqlx::query("INSERT INTO checkout_marker VALUES (17)")
        .execute(&mut *returned)
        .await?;
    drop(returned);
    gate.blocked.store(true, Ordering::SeqCst);
    let mut checkout = Box::pin(pool.acquire());
    assert_waits_for_checkout(&mut checkout, &gate).await?;
    gate.release();
    let mut reused = timeout(CHECKOUT_DEADLINE, checkout).await??;
    let marker: i64 = sqlx::query_scalar("SELECT value FROM checkout_marker")
        .fetch_one(&mut *reused)
        .await?;
    assert_eq!(marker, 17, "the same physical connection must be reused");
    reused.close().await?;
    for connection in held {
        connection.close().await?;
    }
    pool.close().await;
    Ok(())
}

#[tokio::test]
async fn cancelled_checkout_does_not_release_uncoordinated_connection() -> anyhow::Result<()> {
    let fixture = Fixture::new().await?;
    let gate = Arc::new(CheckoutGate::ready());
    let allowed = Arc::new(AtomicBool::new(true));
    let pool = fixture.open(Arc::clone(&allowed), Arc::clone(&gate)).await?;
    let mut held = Vec::new();
    for _ in 0..5 {
        held.push(pool.acquire().await?);
    }
    let mut returned = held.pop().context("fifth connection exists")?;
    sqlx::query("CREATE TEMP TABLE cancelled_checkout_marker (value INTEGER)")
        .execute(&mut *returned)
        .await?;
    drop(returned);
    gate.blocked.store(true, Ordering::SeqCst);
    let mut checkout = Box::pin(pool.acquire());
    assert_waits_for_checkout(&mut checkout, &gate).await?;
    drop(checkout);

    gate.blocked.store(false, Ordering::SeqCst);
    allowed.store(false, Ordering::SeqCst);
    let mut replacement = timeout(CHECKOUT_DEADLINE, pool.acquire()).await??;
    let marker_count: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM sqlite_temp_master WHERE name = 'cancelled_checkout_marker'",
    )
    .fetch_one(&mut *replacement)
    .await?;
    assert_eq!(marker_count, 0, "cancelled checkout must discard its connection");
    assert_commit_veto(
        sqlx::query("INSERT INTO evidence VALUES (6)")
            .execute(&mut *replacement)
            .await
            .expect_err("cancellation must not bypass the replacement commit hook"),
    );
    assert_eq!(fixture.persisted_rows().await?, Vec::<i64>::new());
    replacement.close().await?;
    for connection in held {
        connection.close().await?;
    }
    pool.close().await;
    Ok(())
}
